def run():
    conn = get_connection()
    cur = conn.cursor()

    print("Inserting service_knowledge...")
    for s in services:
        cur.execute("""
            INSERT INTO service_knowledge (
                service_key, service_name, state, jurisdiction_type, category, icon,
                department, portal_name, portal_url, apply_url,
                documents_json, eligibility, fees, timeline,
                photo_size, signature_size, upload_limits, validity,
                application_steps_json, notes, sources_json,
                confidence_score, last_verified, manual_review_needed,
                has_variants, active, version, updated_by
            ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            ON CONFLICT (service_key) DO NOTHING
        """, (
            s["service_key"], s["service_name"], s["state"], s["jurisdiction_type"],
            s["category"], s["icon"], s["department"], s["portal_name"],
            s["portal_url"], s["apply_url"], s["documents_json"], s["eligibility"],
            s["fees"], s["timeline"], s["photo_size"], s["signature_size"],
            s["upload_limits"], s["validity"], s["application_steps_json"],
            s["notes"], s["sources_json"], s["confidence_score"], s["last_verified"],
            s["manual_review_needed"], s["has_variants"], s["active"],
            s["version"], s["updated_by"]
        ))
        print(f"  OK: {s['service_key']}")

    print("\nInserting service_variants...")
    for v in variants:
        cur.execute("""
            INSERT INTO service_variants (
                parent_service_key, variant_key, label, icon,
                department, portal_name, portal_url, apply_url,
                documents_json, eligibility, fees, timeline,
                photo_size, signature_size, upload_limits, validity,
                application_steps_json, notes, sources_json,
                sort_order, active, last_verified, manual_review_needed
            ) VALUES (%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s,%s)
            ON CONFLICT DO NOTHING
        """, (
            v["parent_service_key"], v["variant_key"], v["label"], v["icon"],
            v["department"], v["portal_name"], v["portal_url"], v["apply_url"],
            v["documents_json"], v["eligibility"], v["fees"], v["timeline"],
            v["photo_size"], v["signature_size"], v["upload_limits"], v["validity"],
            v["application_steps_json"], v["notes"], v["sources_json"],
            v["sort_order"], v["active"], v["last_verified"], v["manual_review_needed"]
        ))
        print(f"  OK: {v['parent_service_key']} → {v['label']}")

    conn.commit()
    cur.close()
    conn.close()
    print("\nDone! All data migrated.")

if __name__ == "__main__":
    run()